window.receiveProjectSource({"path": "test/unit/microservices/web_extraction/test_borderline_verifier_unit.py", "lines": ["\"\"\"Unit tests for the borderline LLM verifier's pure-logic units (DAT-6369).", "", "Covers the deterministic pieces that don't need a DB or LLM call:", "", "- ``parse_publisher_hostname`` \u2014 input sanitisation + ``www.``/``m.`` strip", "- ``registrable_domain`` \u2014 eTLD+1 reduction, including the IP-literal short-circuit", "- ``_classify_band`` \u2014 score \u2192 which of the three bands, or None when out of all", "- ``_apply_verdict`` \u2014 LLM-verdict-shape \u2192 ``DeduplicationClassification`` per band", "- ``_safer_on_failure`` \u2014 fallback per band when the LLM call can't complete", "- ``maybe_verify_borderline`` short-circuit when ``DEDUP_VERIFIER_ENABLED`` is off,", "  and its ``verifier_outcome`` log signal (agreed / adjusted / failed)", "- the same-publisher demote in both shadow and enforce mode \u2014 its band restriction,", "  its downgrade-only rule, its verbatim exemption, and the suffix-list over-collapse", "  it inherits", "", "Live-LLM coverage of ``maybe_verify_borderline`` lives in the integration", "suite (``test/integration/web_extraction/test_borderline_verifier.py``).", "\"\"\"", "", "from unittest.mock import AsyncMock, MagicMock, patch", "from uuid import uuid4", "", "import pytest", "", "from common.models.enums import ChatModel", "from microservices.web_extraction.services.helpers import borderline_verifier as bv_mod", "from microservices.web_extraction.services.helpers.borderline_verifier import (", "    _apply_verdict,", "    _Band,", "    _call_llm_verifier,", "    _classify_band,", "    _safer_on_failure,", "    maybe_verify_borderline,", "    parse_publisher_hostname,", "    registrable_domain,", ")", "from microservices.web_extraction.services.helpers.layer_two import (", "    DeduplicationClassification,", ")", "", "pytestmark = pytest.mark.unit", "", "", "# ---------------------------------------------------------------------------", "# parse_publisher_hostname", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.parametrize(", "    \"url,expected\",", "    [", "        (None, None),", "        (\"\", None),", "        (\"not a url at all\", None),", "        (\"https://example.com/article\", \"example.com\"),", "        (\"https://www.example.com/article\", \"example.com\"),", "        (\"https://m.example.com/article\", \"example.com\"),", "        # Only the leading ``www.``/``m.`` is stripped \u2014 multi-level subdomains", "        # below those prefixes are preserved so e.g. desktop / mobile of the", "        # same publisher collapse but distinct subdomains stay distinct.", "        (\"https://news.example.com/article\", \"news.example.com\"),", "        (\"https://www.news.example.com/article\", \"news.example.com\"),", "        # URL with no scheme has no parseable hostname.", "        (\"example.com/article\", None),", "    ],", ")", "def test_parse_publisher_hostname(url, expected):", "    assert parse_publisher_hostname(url) == expected", "", "", "# ---------------------------------------------------------------------------", "# registrable_domain", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.parametrize(", "    \"host,expected\",", "    [", "        # Ordinary reduction to eTLD+1.", "        (\"news.example.com\", \"example.com\"),", "        (\"example.com\", \"example.com\"),", "        # Two-label public suffix keeps a third label.", "        (\"news.bbc.co.uk\", \"bbc.co.uk\"),", "        # Too few labels to reduce.", "        (\"localhost\", \"localhost\"),", "        # IP literals have no registrable domain and must survive whole. Reducing an", "        # IPv4 to its trailing two labels is the false-demote case: 10.0.0.1 and", "        # 192.168.0.1 would both collapse to \"0.1\" and read as one publisher.", "        (\"10.0.0.1\", \"10.0.0.1\"),", "        (\"192.168.0.1\", \"192.168.0.1\"),", "        (\"127.0.0.1\", \"127.0.0.1\"),", "        # IPv6 arrives unbracketed from ``urlparse().hostname``; it has no dots to", "        # split on, so it was already safe \u2014 pinned so that stays true.", "        (\"2001:db8::1\", \"2001:db8::1\"),", "        (\"::1\", \"::1\"),", "    ],", ")", "def test_registrable_domain(host, expected):", "    assert registrable_domain(host) == expected", "", "", "@pytest.mark.parametrize(", "    \"host_a,host_b\",", "    [", "        # Same trailing octets, unrelated hosts \u2014 the exact pair a trailing-label", "        # reduction would have declared same-publisher.", "        (\"10.0.0.1\", \"192.168.0.1\"),", "        (\"203.0.113.5\", \"198.51.100.5\"),", "    ],", ")", "def test_unrelated_ipv4_hosts_are_not_same_publisher(host_a, host_b):", "    \"\"\"Two unrelated IPv4 hosts must never compare as one publisher.", "", "    On the promotion path this over-collapse only forfeited a promotion; on the", "    demote path it produces a false demote once enforcement is on.", "    \"\"\"", "    assert bv_mod.same_publisher(host_a, host_b) is False", "    # An IP literal is still its own publisher when both sides are the same host.", "    assert bv_mod.same_publisher(host_a, host_a) is True", "", "", "# ---------------------------------------------------------------------------", "# _classify_band", "# ---------------------------------------------------------------------------", "", "", "@pytest.fixture", "def _verifier_thresholds():", "    \"\"\"Patch the verifier's view of thresholds + margin to a stable test set.", "", "    Production defaults: DUPLICATE=0.95, SYNDICATION=0.80, MARGIN=0.02,", "    MID_BAND_LOW=0.82, MID_BAND_HIGH=0.90. Tests pin those explicitly so changes", "    to the production defaults don't silently shift band edges out from under the", "    assertions. The mid-band floats must be set here rather than left to the", "    ``MagicMock`` default \u2014 ``_classify_band`` compares them numerically, and a", "    bare mock raises ``TypeError`` on ``<``.", "", "    ``DEDUP_SAME_PUBLISHER_ENFORCE`` is pinned for the opposite reason: an unset", "    bool attribute on a bare ``MagicMock`` is *truthy*, so omitting it would", "    silently run every test in enforce mode. Production default is False.", "    \"\"\"", "    with patch(", "        \"microservices.web_extraction.services.helpers.borderline_verifier.web_config\"", "    ) as mock_config:", "        mock_config.DEDUP_DUPLICATE_THRESHOLD = 0.95", "        mock_config.DEDUP_SYNDICATION_THRESHOLD = 0.80", "        mock_config.DEDUP_VERIFIER_MARGIN = 0.02", "        mock_config.DEDUP_VERIFIER_ENABLED = True", "        mock_config.DEDUP_VERIFIER_MID_BAND_LOW = 0.82", "        mock_config.DEDUP_VERIFIER_MID_BAND_HIGH = 0.90", "        mock_config.DEDUP_SAME_PUBLISHER_ENFORCE = False", "        yield mock_config", "", "", "@pytest.mark.parametrize(", "    \"score,expected_band\",", "    [", "        # NEAR_DUP window: |score - 0.95| <= 0.02. Values pulled inward by 0.001", "        # to dodge the float-rounding cliff on the exact edge (|0.97 - 0.95|", "        # evaluates to 0.020000000000000018 in IEEE-754, which fails <=).", "        (0.95, _Band.NEAR_DUP),", "        (0.94, _Band.NEAR_DUP),", "        (0.969, _Band.NEAR_DUP),", "        # NEAR_SYND window: |score - 0.80| <= 0.02 (same edge dodge as above).", "        (0.80, _Band.NEAR_SYND),", "        (0.785, _Band.NEAR_SYND),", "        (0.819, _Band.NEAR_SYND),", "        # NEAR_MID: the explicit mid-band [0.82, 0.90], evaluated last, so it is", "        # the residual after NEAR_SYND claims its window. Its effective lower edge", "        # is therefore exclusive. 0.821/0.819 straddle that edge without landing on", "        # it: |0.82 - 0.80| evaluates to 0.020000000000000018 in IEEE-754, so an", "        # assertion on 0.82 itself would be decided by float representation rather", "        # than by the band layout.", "        (0.821, _Band.NEAR_MID),", "        (0.85, _Band.NEAR_MID),", "        (0.90, _Band.NEAR_MID),  # upper edge is unambiguous; no other arm claims it", "        # Outside every window", "        (0.50, None),", "        (0.901, None),  # just above the mid-band upper edge", "        # The gap between MID_BAND_HIGH (0.90) and NEAR_DUP's lower edge (0.93) is", "        # intentional \u2014 scores there are confidently mid-syndication, not borderline.", "        (0.92, None),", "        (1.00, None),  # above NEAR_DUP upper edge", "        (0.00, None),", "    ],", ")", "def test_classify_band(_verifier_thresholds, score, expected_band):", "    assert _classify_band(score) == expected_band", "", "", "def test_classify_band_prefers_near_dup_when_score_could_match_both(_verifier_thresholds):", "    \"\"\"Defensive: if the two windows ever overlap (margin grows or thresholds", "    move closer), the NEAR_DUP arm wins because it's checked first. Locks in", "    that decision so a config change can't silently swap band routing.", "    \"\"\"", "    _verifier_thresholds.DEDUP_DUPLICATE_THRESHOLD = 0.90", "    _verifier_thresholds.DEDUP_SYNDICATION_THRESHOLD = 0.88", "    _verifier_thresholds.DEDUP_VERIFIER_MARGIN = (", "        0.05  # windows overlap at [0.85, 0.95] & [0.83, 0.93]", "    )", "", "    # 0.89 is within MARGIN of both 0.90 and 0.88 \u2014 NEAR_DUP must win.", "    assert _classify_band(0.89) == _Band.NEAR_DUP", "", "", "def test_classify_band_mid_band_kill_switch(_verifier_thresholds):", "    \"\"\"``MID_BAND_LOW >= MID_BAND_HIGH`` disables the mid-band entirely, restoring", "    two-band behavior as a config-only rollback with no code deploy.", "    \"\"\"", "    _verifier_thresholds.DEDUP_VERIFIER_MID_BAND_LOW = 0.85", "    _verifier_thresholds.DEDUP_VERIFIER_MID_BAND_HIGH = 0.85", "", "    assert _classify_band(0.85) is None", "    # The two margin windows are unaffected by the mid-band kill switch.", "    assert _classify_band(0.94) == _Band.NEAR_DUP", "    assert _classify_band(0.80) == _Band.NEAR_SYND", "", "", "# ---------------------------------------------------------------------------", "# _apply_verdict \u2014 NEAR_MID band (between the two threshold windows)", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.parametrize(", "    \"verdict,expected\",", "    [", "        (", "            {\"event\": \"same\", \"verbatim\": False, \"reason\": \"serial wire release\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "        (", "            {\"event\": \"different\", \"verbatim\": None, \"reason\": \"distinct deal\"},", "            DeduplicationClassification.UNIQUE,", "        ),", "        # Safer-bias on inconclusive: UNIQUE so a templated near-match doesn't", "        # contaminate the group \u2014 the precision the mid-band exists to protect.", "        (", "            {\"event\": \"inconclusive\", \"verbatim\": None, \"reason\": \"?\"},", "            DeduplicationClassification.UNIQUE,", "        ),", "        ({}, DeduplicationClassification.UNIQUE),", "        ({\"event\": \"garbage\", \"verbatim\": None}, DeduplicationClassification.UNIQUE),", "    ],", ")", "def test_apply_verdict_near_mid(verdict, expected):", "    assert _apply_verdict(_Band.NEAR_MID, verdict) == expected", "", "", "@pytest.mark.parametrize(", "    \"verdict\",", "    [", "        {\"event\": \"same\", \"verbatim\": True, \"reason\": \"verbatim reprint\"},", "        {\"event\": \"same\", \"verbatim\": False, \"reason\": \"rewritten\"},", "        {\"event\": \"same\", \"verbatim\": None, \"reason\": \"ambiguous\"},", "        {\"event\": \"different\", \"verbatim\": True, \"reason\": \"contradictory shape\"},", "        {\"event\": \"inconclusive\", \"verbatim\": True, \"reason\": \"contradictory shape\"},", "        {},", "        {\"event\": \"garbage\", \"verbatim\": True},", "    ],", ")", "def test_apply_verdict_near_mid_never_returns_duplicate(verdict):", "    \"\"\"No verdict shape \u2014 including ``same`` + ``verbatim=True``, which promotes to", "    DUPLICATE in the NEAR_DUP band \u2014 may return DUPLICATE from the mid-band.", "", "    A mid-band score sits far below the duplicate threshold, and DUPLICATE removes", "    the article from the pipeline entirely (no downstream queue, no entity", "    classification, no Accelerate document, no candidate observations).", "    \"\"\"", "    assert _apply_verdict(_Band.NEAR_MID, verdict) != DeduplicationClassification.DUPLICATE", "", "", "# ---------------------------------------------------------------------------", "# _apply_verdict \u2014 NEAR_SYND band (syndication <-> unique)", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.parametrize(", "    \"verdict,expected\",", "    [", "        (", "            {\"event\": \"same\", \"verbatim\": False, \"reason\": \"x\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "        (", "            {\"event\": \"same\", \"verbatim\": None, \"reason\": \"x\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "        (", "            {\"event\": \"different\", \"verbatim\": None, \"reason\": \"x\"},", "            DeduplicationClassification.UNIQUE,", "        ),", "        # Safer-bias on inconclusive: UNIQUE so we don't pollute the group.", "        (", "            {\"event\": \"inconclusive\", \"verbatim\": None, \"reason\": \"x\"},", "            DeduplicationClassification.UNIQUE,", "        ),", "        # Missing/unknown event keys also bias safer.", "        ({}, DeduplicationClassification.UNIQUE),", "        ({\"event\": \"garbage\", \"verbatim\": None}, DeduplicationClassification.UNIQUE),", "    ],", ")", "def test_apply_verdict_near_synd(verdict, expected):", "    assert _apply_verdict(_Band.NEAR_SYND, verdict) == expected", "", "", "# ---------------------------------------------------------------------------", "# _apply_verdict \u2014 NEAR_DUP band (duplicate <-> syndication)", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.parametrize(", "    \"verdict,expected\",", "    [", "        # same + verbatim=True -> DUPLICATE (confirms the high vector score)", "        (", "            {\"event\": \"same\", \"verbatim\": True, \"reason\": \"wire reprint\"},", "            DeduplicationClassification.DUPLICATE,", "        ),", "        # same + verbatim=False -> SYNDICATION_CANDIDATE (same event, different prose)", "        (", "            {\"event\": \"same\", \"verbatim\": False, \"reason\": \"rewritten\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "        # same + verbatim=None fails the identity check -> SYNDICATION_CANDIDATE", "        (", "            {\"event\": \"same\", \"verbatim\": None, \"reason\": \"ambiguous\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "        # same + a truthy non-boolean -> SYNDICATION_CANDIDATE. Only an explicit", "        # ``true`` reaches DUPLICATE, which would drop the article from the", "        # pipeline; ``parse_llm_response_json`` does not validate field types, so", "        # a repaired verdict can supply this shape.", "        (", "            {\"event\": \"same\", \"verbatim\": \"false\", \"reason\": \"rewritten\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "        # different -> UNIQUE (LLM contradicts the high vector score, trust the LLM)", "        (", "            {\"event\": \"different\", \"verbatim\": None, \"reason\": \"different story\"},", "            DeduplicationClassification.UNIQUE,", "        ),", "        # inconclusive -> safer SYNDICATION_CANDIDATE (don't silently drop the article)", "        (", "            {\"event\": \"inconclusive\", \"verbatim\": None, \"reason\": \"?\"},", "            DeduplicationClassification.SYNDICATION_CANDIDATE,", "        ),", "    ],", ")", "def test_apply_verdict_near_dup(verdict, expected):", "    assert _apply_verdict(_Band.NEAR_DUP, verdict) == expected", "", "", "# ---------------------------------------------------------------------------", "# _safer_on_failure", "# ---------------------------------------------------------------------------", "", "", "def test_safer_on_failure():", "    \"\"\"Safer-bias per band: NEAR_SYND falls back to UNIQUE (don't pollute the", "    syndication group with a maybe-unrelated article), NEAR_DUP falls back to", "    SYNDICATION_CANDIDATE (don't silently drop an article the vector score", "    flagged as a likely duplicate).", "", "    The incoming classification is passed for the mid-band's leave-unchanged bias;", "    the two margin bands ignore it and keep their fixed fallbacks.", "    \"\"\"", "    for incoming in (", "        DeduplicationClassification.UNIQUE,", "        DeduplicationClassification.SYNDICATION_CANDIDATE,", "    ):", "        assert _safer_on_failure(_Band.NEAR_SYND, incoming) == DeduplicationClassification.UNIQUE", "        assert (", "            _safer_on_failure(_Band.NEAR_DUP, incoming)", "            == DeduplicationClassification.SYNDICATION_CANDIDATE", "        )", "", "", "@pytest.mark.parametrize(", "    \"incoming\",", "    [", "        DeduplicationClassification.SYNDICATION_CANDIDATE,", "        DeduplicationClassification.UNIQUE,", "    ],", ")", "def test_safer_on_failure_mid_band_leaves_classification_unchanged(incoming):", "    \"\"\"The mid-band has no \"safer\" side: its scores sit near no threshold, so a", "    failed call returns the incoming classification untouched rather than guessing.", "", "    A fixed fallback here would either erase recall (always UNIQUE) or preserve the", "    contamination the band exists to catch (always SYNDICATION_CANDIDATE) on every", "    failed call \u2014 and failures are silent by design.", "    \"\"\"", "    assert _safer_on_failure(_Band.NEAR_MID, incoming) == incoming", "", "", "# ---------------------------------------------------------------------------", "# maybe_verify_borderline \u2014 short-circuit paths", "# ---------------------------------------------------------------------------", "", "", "async def test_maybe_verify_borderline_disabled_flag_is_noop(_verifier_thresholds):", "    \"\"\"``DEDUP_VERIFIER_ENABLED=False`` must short-circuit before any DB read", "    or LLM call \u2014 returns the input classification unchanged with no addendum.", "    \"\"\"", "    _verifier_thresholds.DEDUP_VERIFIER_ENABLED = False", "    db = AsyncMock()", "    api_helper = MagicMock()", "", "    result_cls, addendum = await maybe_verify_borderline(", "        db,", "        api_helper,", "        article_score=0.95,  # squarely in NEAR_DUP if enabled", "        classification=DeduplicationClassification.DUPLICATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=None,", "        matched_article_id=uuid4(),", "        logger=MagicMock(),", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.DUPLICATE", "    assert addendum is None", "    db.execute.assert_not_awaited()", "", "", "async def test_maybe_verify_borderline_out_of_band_is_noop(_verifier_thresholds):", "    \"\"\"Scores outside both bands must short-circuit before any DB read or", "    LLM call \u2014 the verifier exists to second-guess borderline classifications,", "    not to validate confident ones.", "    \"\"\"", "    db = AsyncMock()", "    api_helper = MagicMock()", "", "    result_cls, addendum = await maybe_verify_borderline(", "        db,", "        api_helper,", "        article_score=0.50,  # outside both bands", "        classification=DeduplicationClassification.UNIQUE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=None,", "        matched_article_id=uuid4(),", "        logger=MagicMock(),", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert addendum is None", "    db.execute.assert_not_awaited()", "", "", "# ---------------------------------------------------------------------------", "# maybe_verify_borderline \u2014 score-independent verifier_forced trigger (DAT-7932)", "# ---------------------------------------------------------------------------", "", "", "async def test_verifier_forced_routes_despite_out_of_band_score(_verifier_thresholds, monkeypatch):", "    \"\"\"``verifier_forced=True`` must adjudicate an out-of-band (diluted) score", "    instead of short-circuiting \u2014 the title/headline blocking key relies on it.", "", "    Uses the no-matched-context failure path to prove routing happened without a", "    live LLM: a short-circuit would return ``(input, None)``; routing returns the", "    NEAR_SYND safer fallback (UNIQUE) with a populated addendum.", "    \"\"\"", "", "    async def _no_matched_context(db, matched_article_id):", "        return None", "", "    monkeypatch.setattr(bv_mod, \"_load_matched_context\", _no_matched_context)", "", "    result_cls, addendum = await maybe_verify_borderline(", "        AsyncMock(),", "        MagicMock(),", "        article_score=0.50,  # far outside both bands", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=None,", "        matched_article_id=uuid4(),", "        verifier_forced=True,", "        logger=MagicMock(),", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert addendum is not None", "    assert addendum.get(\"llm_failed\") is True", "", "", "async def test_verifier_forced_is_noop_when_disabled(_verifier_thresholds):", "    \"\"\"The forced flag changes eligibility, not the enable state: with", "    ``DEDUP_VERIFIER_ENABLED=False`` a forced promotion is still a no-op.", "    \"\"\"", "    _verifier_thresholds.DEDUP_VERIFIER_ENABLED = False", "    db = AsyncMock()", "", "    result_cls, addendum = await maybe_verify_borderline(", "        db,", "        MagicMock(),", "        article_score=0.50,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=None,", "        matched_article_id=uuid4(),", "        verifier_forced=True,", "        logger=MagicMock(),", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is None", "    db.execute.assert_not_awaited()", "", "", "async def test_verifier_forced_same_event_confirms_syndication(_verifier_thresholds, monkeypatch):", "    \"\"\"Forced routing + LLM 'same' verdict \u2192 SYNDICATION_CANDIDATE confirmed (the", "    NEAR_SYND same-event mapping), with the verdict recorded in the addendum.", "    \"\"\"", "", "    async def _matched_context(db, matched_article_id):", "        return {\"title\": \"t\", \"lede\": \"lede\", \"published_at\": None, \"publisher\": \"b.com\"}", "", "    async def _fake_llm(", "        api_helper,", "        *,", "        incoming_side,", "        matched_side,", "        api_key,", "        article_id=None,", "        layer_two_activity_id=None,", "    ):", "        return {\"event\": \"same\", \"verbatim\": False, \"reason\": \"wire\"}, \"gpt-test\"", "", "    monkeypatch.setattr(bv_mod, \"_load_matched_context\", _matched_context)", "    monkeypatch.setattr(bv_mod, \"_call_llm_verifier\", _fake_llm)", "", "    result_cls, addendum = await maybe_verify_borderline(", "        AsyncMock(),", "        MagicMock(),", "        article_score=0.50,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=\"https://a.com/x\",", "        matched_article_id=uuid4(),", "        verifier_forced=True,", "        logger=MagicMock(),", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    assert addendum[\"llm_verdict\"] == {\"event\": \"same\", \"verbatim\": False, \"reason\": \"wire\"}", "    assert addendum[\"llm_band\"] == _Band.NEAR_SYND.value", "", "", "# ---------------------------------------------------------------------------", "# maybe_verify_borderline \u2014 mid-band routing + the observability signal", "# ---------------------------------------------------------------------------", "", "", "async def _stub_verifier_llm(monkeypatch, verdict, matched_publisher=\"b.com\"):", "    \"\"\"Stub the matched-context read and the LLM call so no transport runs.\"\"\"", "", "    async def _matched_context(db, matched_article_id):", "        return {", "            \"title\": \"t\",", "            \"lede\": \"lede\",", "            \"published_at\": None,", "            \"publisher\": matched_publisher,", "        }", "", "    async def _fake_llm(", "        api_helper,", "        *,", "        incoming_side,", "        matched_side,", "        api_key,", "        article_id=None,", "        layer_two_activity_id=None,", "    ):", "        return verdict, \"gpt-test\"", "", "    monkeypatch.setattr(bv_mod, \"_load_matched_context\", _matched_context)", "    monkeypatch.setattr(bv_mod, \"_call_llm_verifier\", _fake_llm)", "", "", "async def test_mid_band_agreeing_verdict_still_logs_outcome(_verifier_thresholds, monkeypatch):", "    \"\"\"A verifier call that AGREES with the vector classification must still emit an", "    info log carrying ``verifier_outcome=\"agreed\"``.", "", "    Without it a fired-and-agreed call leaves no trace, so neither call volume nor", "    the agree rate is derivable \u2014 and the shared llm-chat request log can't isolate", "    the verifier from its sibling call sites at the same model and route.", "    \"\"\"", "    await _stub_verifier_llm(monkeypatch, {\"event\": \"same\", \"verbatim\": False, \"reason\": \"wire\"})", "    log = MagicMock()", "", "    result_cls, addendum = await maybe_verify_borderline(", "        AsyncMock(),", "        MagicMock(),", "        article_score=0.85,  # squarely in NEAR_MID", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=\"https://a.com/x\",", "        matched_article_id=uuid4(),", "        logger=log,", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    assert addendum[\"llm_band\"] == _Band.NEAR_MID.value", "", "    log.info.assert_called_once()", "    kwargs = log.info.call_args.kwargs", "    assert kwargs[\"verifier_outcome\"] == \"agreed\"", "    assert kwargs[\"band\"] == _Band.NEAR_MID.value", "    assert kwargs[\"vector_classification\"] == kwargs[\"adjusted_classification\"]", "    # The LLM's free-form reason text must never reach the log index.", "    assert \"wire\" not in repr(kwargs)", "", "", "async def test_mid_band_different_event_demotes_and_logs_adjusted(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"A mid-band ``different`` verdict demotes to UNIQUE and reports", "    ``verifier_outcome=\"adjusted\"`` on the same log field.", "    \"\"\"", "    await _stub_verifier_llm(", "        monkeypatch, {\"event\": \"different\", \"verbatim\": None, \"reason\": \"distinct deal\"}", "    )", "    log = MagicMock()", "", "    result_cls, addendum = await maybe_verify_borderline(", "        AsyncMock(),", "        MagicMock(),", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=\"https://a.com/x\",", "        matched_article_id=uuid4(),", "        logger=log,", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert addendum is not None", "    assert addendum[\"llm_band\"] == _Band.NEAR_MID.value", "    assert log.info.call_args.kwargs[\"verifier_outcome\"] == \"adjusted\"", "", "", "async def test_mid_band_llm_failure_leaves_classification_unchanged(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"A failed mid-band call returns the incoming classification untouched and", "    marks the warning ``verifier_outcome=\"failed\"`` so all three outcomes are", "    countable from one field.", "    \"\"\"", "", "    async def _matched_context(db, matched_article_id):", "        return {\"title\": \"t\", \"lede\": \"lede\", \"published_at\": None, \"publisher\": \"b.com\"}", "", "    async def _boom(api_helper, **kwargs):", "        raise RuntimeError(\"llm exploded\")", "", "    monkeypatch.setattr(bv_mod, \"_load_matched_context\", _matched_context)", "    monkeypatch.setattr(bv_mod, \"_call_llm_verifier\", _boom)", "    log = MagicMock()", "", "    result_cls, addendum = await maybe_verify_borderline(", "        AsyncMock(),", "        MagicMock(),", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=\"https://a.com/x\",", "        matched_article_id=uuid4(),", "        logger=log,", "        api_key=\"sk-test\",", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    assert addendum[\"llm_failed\"] is True", "    assert log.warning.call_args.kwargs[\"verifier_outcome\"] == \"failed\"", "", "", "# ---------------------------------------------------------------------------", "# maybe_verify_borderline \u2014 same-publisher demote (shadow / enforce)", "# ---------------------------------------------------------------------------", "", "_SAME_EVENT = {\"event\": \"same\", \"verbatim\": False, \"reason\": \"serial wire release\"}", "", "", "async def _run_verifier(*, article_score, classification, incoming_url, log):", "    \"\"\"Invoke the verifier with the boilerplate args the demote cases don't vary.\"\"\"", "    return await maybe_verify_borderline(", "        AsyncMock(),", "        MagicMock(),", "        article_score=article_score,", "        classification=classification,", "        incoming_title=\"t\",", "        incoming_lede=\"lede\",", "        incoming_published_at=None,", "        incoming_url=incoming_url,", "        matched_article_id=uuid4(),", "        logger=log,", "        api_key=\"sk-test\",", "    )", "", "", "async def test_same_publisher_shadow_records_signal_without_demoting(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"With ``DEDUP_SAME_PUBLISHER_ENFORCE=False`` the signal is recorded and logged", "    but changes nothing \u2014 the returned classification is what the verdict alone", "    produced, so merging the demote cannot alter a single production classification.", "    \"\"\"", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,  # squarely in NEAR_MID", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"is_same_publisher\"] is True", "    assert signal[\"eligible\"] is True", "    assert signal[\"enforced\"] is False", "    assert signal[\"incoming_publisher\"] == \"example.com\"", "    assert signal[\"matched_publisher\"] == \"example.com\"", "", "    kwargs = log.info.call_args.kwargs", "    assert kwargs[\"same_publisher\"] is True", "    assert kwargs[\"publisher_demote\"] == \"would_apply\"", "    # The verdict agreed with the vector classification; the demote reports separately.", "    assert kwargs[\"verifier_outcome\"] == \"agreed\"", "    # Hostnames belong in match_info, not the log index.", "    assert \"example.com\" not in repr(kwargs)", "", "", "async def test_same_publisher_enforce_demotes_to_unique(_verifier_thresholds, monkeypatch):", "    \"\"\"Enforcing turns the same inputs into a demote: a same-publisher mid-band", "    ``SYNDICATION_CANDIDATE`` becomes UNIQUE and the log says ``applied``.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert addendum is not None", "    assert addendum[\"same_publisher\"][\"enforced\"] is True", "    kwargs = log.info.call_args.kwargs", "    assert kwargs[\"publisher_demote\"] == \"applied\"", "    assert kwargs[\"adjusted_classification\"] == DeduplicationClassification.UNIQUE.value", "", "", "async def test_cross_publisher_enforce_leaves_syndication_intact(_verifier_thresholds, monkeypatch):", "    \"\"\"Cross-publisher is what genuine syndication looks like, so the demote must not", "    fire on it even when enforcing \u2014 the recall path DAT-7932 opened stays open.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=\"other.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    assert addendum[\"same_publisher\"][\"is_same_publisher\"] is False", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"none\"", "", "", "async def test_same_publisher_demote_never_reaches_near_dup_band(_verifier_thresholds, monkeypatch):", "    \"\"\"The demote is barred from NEAR_DUP: a near-identical same-publisher pair is", "    far likelier one article re-fetched or self-republished than two events, and the", "    band's own verdict map already adjudicates it.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(", "        monkeypatch,", "        {\"event\": \"same\", \"verbatim\": True, \"reason\": \"wire reprint\"},", "        matched_publisher=\"example.com\",", "    )", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.95,  # squarely in NEAR_DUP", "        classification=DeduplicationClassification.DUPLICATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.DUPLICATE", "    assert addendum is not None", "    assert addendum[\"same_publisher\"][\"is_same_publisher\"] is True", "    assert addendum[\"same_publisher\"][\"eligible\"] is False", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"none\"", "", "", "async def test_same_publisher_demote_is_noop_when_verdict_already_unique(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"Downgrade-only: the signal acts on a SYNDICATION_CANDIDATE verdict and nothing", "    else. A verdict that already resolved to UNIQUE needs no demote, so the call is", "    not eligible and the log must not claim a demote it didn't make.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(", "        monkeypatch,", "        {\"event\": \"different\", \"verbatim\": None, \"reason\": \"distinct deal\"},", "        matched_publisher=\"example.com\",", "    )", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert addendum is not None", "    assert addendum[\"same_publisher\"][\"eligible\"] is False", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"none\"", "", "", "async def test_absent_hostnames_are_not_treated_as_same_publisher(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"Absence is not identity: two unknown hostnames must not compare equal, or the", "    demote would fire on every pair whose URLs failed to parse.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=None)", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=None,", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    assert addendum[\"same_publisher\"][\"is_same_publisher\"] is False", "    assert addendum[\"same_publisher\"][\"incoming_publisher\"] is None", "    assert addendum[\"same_publisher\"][\"matched_publisher\"] is None", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"none\"", "", "", "@pytest.mark.parametrize(", "    \"incoming_url,matched_publisher\",", "    [", "        # Sibling subdomains of one publisher network.", "        (\"https://news.example.com/x\", \"sports.example.com\"),", "        # Bare domain vs. one of its subdomains.", "        (\"https://example.com/x\", \"news.example.com\"),", "        # ``www.`` / ``m.`` are stripped before the registrable-domain reduction.", "        (\"https://www.example.com/x\", \"m.example.com\"),", "        # A two-label public suffix keeps its third label, so these stay one publisher.", "        (\"https://news.bbc.co.uk/x\", \"sport.bbc.co.uk\"),", "    ],", ")", "async def test_registrable_domain_variants_count_as_same_publisher(", "    _verifier_thresholds, monkeypatch, incoming_url, matched_publisher", "):", "    \"\"\"Publisher identity is the registrable domain, so subdomain siblings and", "    desktop/mobile variants of one publisher are all \"same publisher\" and demote.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=matched_publisher)", "    log = MagicMock()", "", "    result_cls, _addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=incoming_url,", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"applied\"", "", "", "@pytest.mark.parametrize(\"enforcing\", [True, False])", "async def test_same_publisher_demote_covers_near_synd_band(", "    _verifier_thresholds, monkeypatch, enforcing", "):", "    \"\"\"NEAR_SYND is the demote's second eligible band and needs its own coverage.", "", "    Every other demote case runs at 0.85 (NEAR_MID), so a refactor could drop", "    NEAR_SYND from the eligibility tuple with the whole suite still green. Both", "    modes are asserted: shadow records ``would_apply`` and changes nothing, enforce", "    demotes to UNIQUE.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = enforcing", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.80,  # squarely in NEAR_SYND", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert addendum is not None", "    assert addendum[\"llm_band\"] == _Band.NEAR_SYND.value", "    assert addendum[\"same_publisher\"][\"eligible\"] is True", "    assert addendum[\"same_publisher\"][\"is_same_publisher\"] is True", "", "    kwargs = log.info.call_args.kwargs", "    if enforcing:", "        assert result_cls == DeduplicationClassification.UNIQUE", "        assert kwargs[\"publisher_demote\"] == \"applied\"", "    else:", "        assert result_cls == DeduplicationClassification.SYNDICATION_CANDIDATE", "        assert kwargs[\"publisher_demote\"] == \"would_apply\"", "", "", "async def test_llm_failure_carries_publisher_pair_signal(_verifier_thresholds, monkeypatch):", "    \"\"\"The LLM-failure path must carry the publisher-pair signal.", "", "    Enforcement is gated on a demote rate measured from verdict-reaching calls. If", "    failures correlate with publisher-pair status, that rate is censored \u2014 so the", "    failure path records the pair to make the correlation checkable. ``eligible`` and", "    ``enforced`` are absent by design: both depend on a verdict that never arrived.", "    \"\"\"", "", "    async def _matched_context(db, matched_article_id):", "        return {\"title\": \"t\", \"lede\": \"lede\", \"published_at\": None, \"publisher\": \"example.com\"}", "", "    async def _boom(api_helper, **kwargs):", "        raise RuntimeError(\"llm exploded\")", "", "    monkeypatch.setattr(bv_mod, \"_load_matched_context\", _matched_context)", "    monkeypatch.setattr(bv_mod, \"_call_llm_verifier\", _boom)", "    log = MagicMock()", "", "    _result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://news.example.com/x\",", "        log=log,", "    )", "", "    assert addendum is not None", "    assert addendum[\"llm_failed\"] is True", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"is_same_publisher\"] is True", "    assert signal[\"incoming_publisher\"] == \"news.example.com\"", "    assert signal[\"matched_publisher\"] == \"example.com\"", "    # A verdict never arrived, so neither eligibility nor the gate is reportable.", "    assert \"eligible\" not in signal", "    assert \"enforced\" not in signal", "", "    kwargs = log.warning.call_args.kwargs", "    assert kwargs[\"verifier_outcome\"] == \"failed\"", "    assert kwargs[\"same_publisher\"] is True", "    # Hostnames belong in match_info, not the log index.", "    assert \"example.com\" not in repr(kwargs)", "", "", "async def test_no_matched_context_failure_carries_no_publisher_signal(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"The no-zyte-row failure returns before either hostname is resolvable.", "", "    Emitting ``is_same_publisher=False`` there would read as \"confirmed", "    cross-publisher\" when the truth is \"unknown\", so the field stays absent.", "    \"\"\"", "", "    async def _no_matched_context(db, matched_article_id):", "        return None", "", "    monkeypatch.setattr(bv_mod, \"_load_matched_context\", _no_matched_context)", "    log = MagicMock()", "", "    _result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert addendum is not None", "    assert addendum[\"llm_failed\"] is True", "    assert addendum[\"reason\"] == \"matched_article_has_no_zyte_article\"", "    assert \"same_publisher\" not in addendum", "    assert \"same_publisher\" not in log.warning.call_args.kwargs", "", "", "async def test_unlisted_two_label_suffix_over_collapses_into_a_false_demote(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"KNOWN FALSE-DEMOTE RISK, pinned deliberately \u2014 not desirable behavior.", "", "    ``TWO_LABEL_PUBLIC_SUFFIXES`` is a curated short list, so an unlisted two-label", "    suffix (``co.ke`` here) leaves both hosts reducing to the suffix itself. Two", "    genuinely different publishers therefore read as one, and under enforcement a", "    real cross-publisher syndication is split. On the promotion path that same", "    over-collapse merely forfeited a promotion; under a penalty it is destructive.", "    This test exists so any future change to the suffix list has a visible baseline.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _SAME_EVENT, matched_publisher=\"beta.co.ke\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://alpha.co.ke/x\",", "        log=log,", "    )", "", "    assert result_cls == DeduplicationClassification.UNIQUE", "    assert addendum is not None", "    assert addendum[\"same_publisher\"][\"is_same_publisher\"] is True", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"applied\"", "", "", "# ---------------------------------------------------------------------------", "# maybe_verify_borderline \u2014 the verbatim exemption on the same-publisher demote", "# ---------------------------------------------------------------------------", "", "_VERBATIM_EVENT = {\"event\": \"same\", \"verbatim\": True, \"reason\": \"identical body text\"}", "", "# The demote's two eligible bands. NEAR_DUP is excluded by band membership, so a", "# single high score would prove nothing about the verbatim term.", "_DEMOTE_BANDS = [", "    pytest.param(0.85, _Band.NEAR_MID, id=\"near_mid\"),", "    pytest.param(0.80, _Band.NEAR_SYND, id=\"near_synd\"),", "]", "", "", "def _assert_eligible_and_skip_are_exclusive(signal):", "    \"\"\"``eligible`` and ``verbatim_skipped`` must never both be true.", "", "    Measurement queries spanning the deploy boundary reconstruct the pre-change", "    population as ``is_same_publisher AND (eligible OR verbatim_skipped)``. If both", "    can be true at once that identity double-counts, so the exclusion is asserted", "    on every case in this section rather than in one isolated test.", "    \"\"\"", "    assert not (signal[\"eligible\"] and signal[\"verbatim_skipped\"])", "", "", "@pytest.mark.parametrize(\"article_score,expected_band\", _DEMOTE_BANDS)", "async def test_verbatim_republish_keeps_its_join_when_enforcing(", "    _verifier_thresholds, monkeypatch, article_score, expected_band", "):", "    \"\"\"A same-publisher pair the verdict calls verbatim keeps its syndication join.", "", "    An outlet republishing its own article word-for-word is real syndication, not", "    two events, and it is the dominant false-split class among the pairs this demote", "    would take. Both eligible bands are exercised: the term lives in the shared band", "    predicate, so a regression that dropped one band would otherwise stay green.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _VERBATIM_EVENT, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=article_score,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls is DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    assert addendum[\"llm_band\"] == expected_band.value", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"is_same_publisher\"] is True", "    assert signal[\"eligible\"] is False", "    assert signal[\"verbatim_skipped\"] is True", "    _assert_eligible_and_skip_are_exclusive(signal)", "", "    kwargs = log.info.call_args.kwargs", "    assert kwargs[\"publisher_demote\"] == \"skipped_verbatim\"", "    assert kwargs[\"llm_verbatim\"] is True", "    # Hostnames belong in match_info, not the log index \u2014 including on the new arm.", "    assert \"example.com\" not in repr(kwargs)", "", "", "@pytest.mark.parametrize(", "    \"verdict\",", "    [", "        pytest.param({\"event\": \"same\", \"verbatim\": False, \"reason\": \"rewritten\"}, id=\"false\"),", "        # ``null`` is what the prompt contract emits when the event is not \"same\"; a", "        # malformed response can still produce it alongside \"same\".", "        pytest.param({\"event\": \"same\", \"verbatim\": None, \"reason\": \"rewritten\"}, id=\"null\"),", "        pytest.param({\"event\": \"same\", \"reason\": \"rewritten\"}, id=\"key_absent\"),", "        # ``parse_llm_response_json`` validates dict-ness only, and its", "        # ``json_repair`` pass can emit any type for the field. A truthy", "        # non-boolean must not exempt the pair, so the gate is an identity check.", "        pytest.param(", "            {\"event\": \"same\", \"verbatim\": \"false\", \"reason\": \"rewritten\"},", "            id=\"truthy_non_bool\",", "        ),", "    ],", ")", "async def test_non_verbatim_same_publisher_pair_is_still_demoted(", "    _verifier_thresholds, monkeypatch, verdict", "):", "    \"\"\"The flag is tri-state, and only an explicit ``true`` exempts.", "", "    ``false``, ``null``, a missing key and a truthy non-boolean all read the same,", "    so the gate is a strict narrowing: nothing that is demoted today stops being", "    demoted for any other reason.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, verdict, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls is DeduplicationClassification.UNIQUE", "    assert addendum is not None", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"eligible\"] is True", "    assert signal[\"verbatim_skipped\"] is False", "    _assert_eligible_and_skip_are_exclusive(signal)", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"applied\"", "", "", "async def test_verbatim_pair_is_excluded_from_would_apply_telemetry(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"In shadow mode the verbatim pair must not be counted as a would-be demote.", "", "    The would-apply arm is derived from ``eligible``, which is why the verbatim term", "    lives in the eligibility computation rather than in the enforce gate \u2014 projecting", "    the enforce decision from ``would_apply`` counts that include verbatim pairs would", "    overstate what enforcement is about to split.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = False", "    await _stub_verifier_llm(monkeypatch, _VERBATIM_EVENT, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls is DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"eligible\"] is False", "    assert signal[\"verbatim_skipped\"] is True", "    assert signal[\"enforced\"] is False", "    _assert_eligible_and_skip_are_exclusive(signal)", "", "    kwargs = log.info.call_args.kwargs", "    assert kwargs[\"publisher_demote\"] != \"would_apply\"", "    assert kwargs[\"publisher_demote\"] == \"skipped_verbatim\"", "", "", "async def test_cross_publisher_verbatim_pair_records_no_verbatim_skip(", "    _verifier_thresholds, monkeypatch", "):", "    \"\"\"``verbatim_skipped`` carries an ``is_same_publisher`` term, deliberately.", "", "    A cross-publisher verbatim pair keeps its join for the ordinary reason \u2014 the", "    demote never applied to it \u2014 so marking it as a verbatim skip would inflate the", "    skip count with pairs the demote was never going to take. The scope limit is what", "    makes ``is_same_publisher AND (eligible OR verbatim_skipped)`` a same-publisher", "    identity rather than a global one.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _VERBATIM_EVENT, matched_publisher=\"other.com\")", "    log = MagicMock()", "", "    result_cls, addendum = await _run_verifier(", "        article_score=0.85,", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert result_cls is DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert addendum is not None", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"is_same_publisher\"] is False", "    assert signal[\"verbatim_skipped\"] is False", "    _assert_eligible_and_skip_are_exclusive(signal)", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"none\"", "", "", "async def test_near_dup_verbatim_pair_records_no_verbatim_skip(_verifier_thresholds, monkeypatch):", "    \"\"\"The skip is scoped to the demote's own bands, not to every verbatim verdict.", "", "    ``NEAR_DUP`` has its own verdict map and the demote never reaches it, so a", "    verbatim skip recorded there would claim the demote declined a pair it was never", "    offered \u2014 and would break the reconstruction identity, which assumes", "    ``verbatim_skipped`` only ever marks pairs inside the demote band.", "    \"\"\"", "    _verifier_thresholds.DEDUP_SAME_PUBLISHER_ENFORCE = True", "    await _stub_verifier_llm(monkeypatch, _VERBATIM_EVENT, matched_publisher=\"example.com\")", "    log = MagicMock()", "", "    _result_cls, addendum = await _run_verifier(", "        article_score=0.95,  # squarely in NEAR_DUP", "        classification=DeduplicationClassification.DUPLICATE,", "        incoming_url=\"https://example.com/x\",", "        log=log,", "    )", "", "    assert addendum is not None", "    signal = addendum[\"same_publisher\"]", "    assert signal[\"is_same_publisher\"] is True", "    assert signal[\"eligible\"] is False", "    assert signal[\"verbatim_skipped\"] is False", "    _assert_eligible_and_skip_are_exclusive(signal)", "    assert log.info.call_args.kwargs[\"publisher_demote\"] == \"none\"", "", "", "# ---------------------------------------------------------------------------", "# _call_llm_verifier \u2014 reported model on failover", "# ---------------------------------------------------------------------------", "", "", "_VERDICT_ENVELOPE = {\"choices\": [{\"content\": '{\"event\": \"same\", \"verbatim\": false}'}]}", "", "", "async def _run_call_llm_verifier(monkeypatch, content, *, article_id=None):", "    \"\"\"Invoke ``_call_llm_verifier`` with the transport and audit write stubbed out.\"\"\"", "", "    async def _fake_raw_call(api_helper, params, *, sys_prompt, usr_prompt, **kwargs):", "        return content, {}", "", "    audit_calls = []", "", "    async def _fake_audit(raw_resp, *, article_id, flow, **kwargs):", "        audit_calls.append(raw_resp)", "", "    monkeypatch.setattr(bv_mod, \"raw_llm_chat_call\", _fake_raw_call)", "    monkeypatch.setattr(bv_mod, \"audit_failover_event\", _fake_audit)", "", "    verdict, model_used = await _call_llm_verifier(", "        MagicMock(),", "        incoming_side=\"A\",", "        matched_side=\"B\",", "        article_id=article_id,", "        api_key=\"sk-test\",", "    )", "    return verdict, model_used, audit_calls", "", "", "async def test_call_llm_verifier_reports_served_model_on_failover(monkeypatch):", "    \"\"\"On failover the reported model must be the one that actually served the call.", "", "    The failover audit row already recorded the served model; returning the", "    configured default here made ``llm_model`` in match_info and the verifier log", "    disagree with it, so model-level failure-rate analysis read the wrong model.", "    \"\"\"", "    content = dict(", "        _VERDICT_ENVELOPE,", "        processed_via_failover=True,", "        served_chat_model=\"claude-haiku-4-5\",", "        original_chat_model=\"gpt-5.4-nano\",", "    )", "", "    _verdict, model_used, audit_calls = await _run_call_llm_verifier(", "        monkeypatch, content, article_id=str(uuid4())", "    )", "", "    assert model_used == \"claude-haiku-4-5\"", "    # The audit row still fires on the same response.", "    assert len(audit_calls) == 1", "", "", "async def test_call_llm_verifier_reports_default_model_without_failover(monkeypatch):", "    \"\"\"No failover means the configured default served the call and is reported.\"\"\"", "    _verdict, model_used, audit_calls = await _run_call_llm_verifier(", "        monkeypatch, dict(_VERDICT_ENVELOPE), article_id=str(uuid4())", "    )", "", "    assert model_used == bv_mod._VERIFIER_PARAMS.default_chat_model.value", "    assert audit_calls == []", "", "", "async def test_call_llm_verifier_falls_back_to_requested_failover_model(monkeypatch):", "    \"\"\"A failover response that omits ``served_chat_model`` reports the requested", "    failover model, not the default.", "", "    ``processed_via_failover=True`` is proof the default did not serve the call, so", "    naming it would be a known-wrong attribution; the requested failover model is the", "    only one the call could have fallen through to.", "    \"\"\"", "    content = dict(_VERDICT_ENVELOPE, processed_via_failover=True)", "", "    _verdict, model_used, _audit_calls = await _run_call_llm_verifier(", "        monkeypatch, content, article_id=str(uuid4())", "    )", "", "    assert model_used == ChatModel.CLAUDE_HAIKU_4_5.value", "    assert model_used != bv_mod._VERIFIER_PARAMS.default_chat_model.value", "", "", "async def test_call_llm_verifier_reports_served_model_without_article_id(monkeypatch):", "    \"\"\"The served-model fix is independent of the audit write.", "", "    ``article_id=None`` skips the audit row, but the model reported must still be", "    the one that served the call.", "    \"\"\"", "    content = dict(", "        _VERDICT_ENVELOPE, processed_via_failover=True, served_chat_model=\"claude-haiku-4-5\"", "    )", "", "    _verdict, model_used, audit_calls = await _run_call_llm_verifier(", "        monkeypatch, content, article_id=None", "    )", "", "    assert model_used == \"claude-haiku-4-5\"", "    assert audit_calls == []", "", "", "# ---------------------------------------------------------------------------", "# _VERIFIER_PARAMS token cap", "# ---------------------------------------------------------------------------", "", "", "def test_verifier_max_tokens_stays_within_accelerate_ceiling():", "    \"\"\"The outbound ``max_tokens`` must stay inside the value Accelerate accepts.", "", "    Accelerate's ``InboundLLMChatRequestSchema.max_tokens`` is bound with", "    ``le=LLMDefaults.MAX_OUTPUT_TOKENS_MAX`` (16,384) and nothing on that path clamps", "    an over-large value, so a higher cap is rejected with HTTP 422 and the call never", "    reaches the model. Raising the cap therefore requires a matching change in the", "    ``accelerate`` repo, which this assertion forces a reader to notice.", "    \"\"\"", "    assert bv_mod._ACCELERATE_MAX_OUTPUT_TOKENS == 16384", "    assert bv_mod._VERIFIER_PARAMS.default_max_tokens <= bv_mod._ACCELERATE_MAX_OUTPUT_TOKENS"], "blocks": [{"start": 1, "end": 48, "label": "Imports and module setup"}, {"start": 49, "end": 75, "label": "def test_parse_publisher_hostname"}, {"start": 76, "end": 101, "label": "def test_registrable_domain"}, {"start": 102, "end": 126, "label": "def test_unrelated_ipv4_hosts_are_not_same_publisher"}, {"start": 127, "end": 154, "label": "def _verifier_thresholds"}, {"start": 155, "end": 190, "label": "def test_classify_band"}, {"start": 191, "end": 205, "label": "def test_classify_band_prefers_near_dup_when_score_could_match_both"}, {"start": 206, "end": 223, "label": "def test_classify_band_mid_band_kill_switch"}, {"start": 224, "end": 248, "label": "def test_apply_verdict_near_mid"}, {"start": 249, "end": 276, "label": "def test_apply_verdict_near_mid_never_returns_duplicate"}, {"start": 277, "end": 310, "label": "def test_apply_verdict_near_synd"}, {"start": 311, "end": 357, "label": "def test_apply_verdict_near_dup"}, {"start": 358, "end": 377, "label": "def test_safer_on_failure"}, {"start": 378, "end": 400, "label": "def test_safer_on_failure_mid_band_leaves_classification_unchanged"}, {"start": 401, "end": 427, "label": "def test_maybe_verify_borderline_disabled_flag_is_noop"}, {"start": 428, "end": 459, "label": "def test_maybe_verify_borderline_out_of_band_is_noop"}, {"start": 460, "end": 493, "label": "def test_verifier_forced_routes_despite_out_of_band_score"}, {"start": 494, "end": 520, "label": "def test_verifier_forced_is_noop_when_disabled"}, {"start": 521, "end": 568, "label": "def test_verifier_forced_same_event_confirms_syndication"}, {"start": 569, "end": 594, "label": "def _stub_verifier_llm"}, {"start": 595, "end": 632, "label": "def test_mid_band_agreeing_verdict_still_logs_outcome"}, {"start": 633, "end": 663, "label": "def test_mid_band_different_event_demotes_and_logs_adjusted"}, {"start": 664, "end": 708, "label": "def test_mid_band_llm_failure_leaves_classification_unchanged"}, {"start": 709, "end": 725, "label": "def _run_verifier"}, {"start": 726, "end": 760, "label": "def test_same_publisher_shadow_records_signal_without_demoting"}, {"start": 761, "end": 783, "label": "def test_same_publisher_enforce_demotes_to_unique"}, {"start": 784, "end": 804, "label": "def test_cross_publisher_enforce_leaves_syndication_intact"}, {"start": 805, "end": 831, "label": "def test_same_publisher_demote_never_reaches_near_dup_band"}, {"start": 832, "end": 859, "label": "def test_same_publisher_demote_is_noop_when_verdict_already_unique"}, {"start": 860, "end": 884, "label": "def test_absent_hostnames_are_not_treated_as_same_publisher"}, {"start": 885, "end": 918, "label": "def test_registrable_domain_variants_count_as_same_publisher"}, {"start": 919, "end": 954, "label": "def test_same_publisher_demote_covers_near_synd_band"}, {"start": 955, "end": 997, "label": "def test_llm_failure_carries_publisher_pair_signal"}, {"start": 998, "end": 1026, "label": "def test_no_matched_context_failure_carries_no_publisher_signal"}, {"start": 1027, "end": 1069, "label": "def test_unlisted_two_label_suffix_over_collapses_into_a_false_demote"}, {"start": 1070, "end": 1080, "label": "def _assert_eligible_and_skip_are_exclusive"}, {"start": 1081, "end": 1118, "label": "def test_verbatim_republish_keeps_its_join_when_enforcing"}, {"start": 1119, "end": 1164, "label": "def test_non_verbatim_same_publisher_pair_is_still_demoted"}, {"start": 1165, "end": 1198, "label": "def test_verbatim_pair_is_excluded_from_would_apply_telemetry"}, {"start": 1199, "end": 1229, "label": "def test_cross_publisher_verbatim_pair_records_no_verbatim_skip"}, {"start": 1230, "end": 1265, "label": "def test_near_dup_verbatim_pair_records_no_verbatim_skip"}, {"start": 1266, "end": 1289, "label": "def _run_call_llm_verifier"}, {"start": 1290, "end": 1312, "label": "def test_call_llm_verifier_reports_served_model_on_failover"}, {"start": 1313, "end": 1322, "label": "def test_call_llm_verifier_reports_default_model_without_failover"}, {"start": 1323, "end": 1340, "label": "def test_call_llm_verifier_falls_back_to_requested_failover_model"}, {"start": 1341, "end": 1363, "label": "def test_call_llm_verifier_reports_served_model_without_article_id"}, {"start": 1364, "end": 1374, "label": "def test_verifier_max_tokens_stays_within_accelerate_ceiling"}], "lineCount": 1374, "sha256": "9e9a478d000f8b70526cbaf63fe4175563d031b4a64a59740f1bba6ae019f6ab", "endsWithNewline": true});
